    # Add at the START of the existing post_install do |installer| block in ios/Podfile
    # (generated by 
px expo prebuild --platform ios).
    # Xcode 27 builds iOS 15+ only; some pods (e.g. SDWebImage) still declare older targets.
    installer.pods_project.targets.each do |t|
      t.build_configurations.each { |c| c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.1' }
    end